sys_ux_data_broker_transform.script:
function transform() { 
    // System property name containing the JSON array of scripts
    var additionalProperties = 'sam.implementation.customscripts';

    // Object to hold the result
    var result = {
        'custom_scripts': []
    };

    // Function to fetch the JSON properties from sam.implementation.customscripts
    function fetchScripts(propertyName) {
        try {
            var propertiesString = gs.getProperty(propertyName); // Get the JSON string
            if (propertiesString) {
                return JSON.parse(propertiesString); // Parse JSON into an array
            }
        } catch (e) {
            gs.log("Error parsing scripts from " + propertyName + ": " + e.message);
        }
        return []; // Return empty array in case of error
    }

    // Fetch the list of scripts from the sam.implementation.customscripts JSON
    var scriptList = fetchScripts(additionalProperties);

    // Process each script and add it to the result array
    scriptList.forEach(function (item) {
        if (item.script) {
            result.custom_scripts.push({
                'script': item.script.trim(),
                'description': item.Description ? item.Description.trim() : "No description provided"
            });
        }
    });

    // Return the final result object
    return result;
}
